import{_ as r,W as a,X as d,$ as e,a0 as i,Z as l,a2 as n,C as s}from"./framework-6a3aa88c.js";const o={},c=n(`<h1 id="kubernetes-系统课总纲" tabindex="-1"><a class="header-anchor" href="#kubernetes-系统课总纲" aria-hidden="true">#</a> Kubernetes 系统课总纲</h1><h2 id="一、结课时你要具备什么能力" tabindex="-1"><a class="header-anchor" href="#一、结课时你要具备什么能力" aria-hidden="true">#</a> 一、结课时你要具备什么能力</h2><p>结课不是「视频看完」或「命令抄完」，而是能独立完成下面五件事：</p><ol><li><strong>讲清楚</strong>：用自己的话解释 Pod、Deployment、Service、Ingress、PVC 等对象为什么存在。</li><li><strong>部署好</strong>：把前端、后端、配置和数据层部署进集群，并完成升级与回滚。</li><li><strong>看得见</strong>：能从对象状态、Events、日志、指标和网络路径收集证据。</li><li><strong>查得准</strong>：面对 Pending、CrashLoopBackOff、ImagePullBackOff、服务不通等问题，沿链路定位而不是碰运气。</li><li><strong>守得住</strong>：理解资源边界、健康检查、权限、备份、高可用和变更风险。</li></ol><p>这门课不承诺把所有 Kubernetes API 都讲完。它要建立一张可靠的地图，让你以后遇到陌生对象也知道该从哪里查。</p><h2 id="二、两条贯穿全课的主线" tabindex="-1"><a class="header-anchor" href="#二、两条贯穿全课的主线" aria-hidden="true">#</a> 二、两条贯穿全课的主线</h2><h3 id="主线-a-控制链-期望如何变成现实" tabindex="-1"><a class="header-anchor" href="#主线-a-控制链-期望如何变成现实" aria-hidden="true">#</a> 主线 A：控制链（期望如何变成现实）</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>YAML / kubectl
      ↓
kube-apiserver → etcd 保存状态
      ↓
控制器发现差距 → 创建/更新对象
      ↓
scheduler 为未调度 Pod 选择 Node
      ↓
kubelet 驱动容器运行时 → 容器真正运行
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以后看到「为什么没创建」「为什么没调度」「为什么没启动」，先判断卡在这条链的哪一段。</p><h3 id="主线-b-请求链-流量如何找到不断变化的-pod" tabindex="-1"><a class="header-anchor" href="#主线-b-请求链-流量如何找到不断变化的-pod" aria-hidden="true">#</a> 主线 B：请求链（流量如何找到不断变化的 Pod）</h3><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>集群外客户端
   ↓
Ingress / Gateway / LoadBalancer
   ↓
Service（稳定入口）
   ↓
EndpointSlice（当前健康后端清单）
   ↓
Pod IP : containerPort
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>以后看到「浏览器不通」「域名能解析但 502」「Service 没后端」，沿这条链逐跳验证。</p><h2 id="三、课程阶段" tabindex="-1"><a class="header-anchor" href="#三、课程阶段" aria-hidden="true">#</a> 三、课程阶段</h2><p>默认采用循序渐进的快速吸收模式：每课只引入一个核心概念，先实操看到结果，再解释术语和原理。减少低价值记忆，但不跳过基础。</p><table><thead><tr><th>阶段</th><th style="text-align:right;">建议周数</th><th>核心内容</th><th>阶段作品 / 过关标准</th></tr></thead><tbody><tr><td>0. 建立地图</td><td style="text-align:right;">0.5</td><td>K8s 解决什么、集群组件、API 对象、kubectl 观察法</td><td>能读懂控制链，分清期望状态和实际状态</td></tr><tr><td>1. 工作负载</td><td style="text-align:right;">1</td><td>Pod、标签、Deployment、ReplicaSet、滚动更新、回滚、Job/CronJob</td><td>发布并回滚一个无状态 Web 服务</td></tr><tr><td>2. 配置与访问</td><td style="text-align:right;">1</td><td>Namespace、ConfigMap、Secret、Service、DNS、Ingress</td><td>配置外置；前后端通过稳定服务名通信</td></tr><tr><td>3. 数据与可靠性</td><td style="text-align:right;">1</td><td>Volume、PV/PVC、StorageClass、StatefulSet、探针、requests/limits</td><td>Pod 重建后数据仍在；错误实例不接流量</td></tr><tr><td>4. 调度与安全</td><td style="text-align:right;">1</td><td>调度约束、污点容忍、驱逐、ServiceAccount、RBAC、SecurityContext</td><td>解释 Pending；给账号最小权限</td></tr><tr><td>5. 可观测与排障</td><td style="text-align:right;">1</td><td>Events、日志、exec/debug、指标、审计思路、故障树</td><td>完成一组未知故障的证据化定位</td></tr><tr><td>6. 交付与运维</td><td style="text-align:right;">1</td><td>Kustomize、Helm、镜像策略、升级回滚、备份、高可用与容量认知</td><td>用 Helm/Kustomize 管理多环境发布</td></tr><tr><td>结业项目</td><td style="text-align:right;">1+</td><td>完整应用上线与演练</td><td>部署、升级、故障注入、恢复、复盘全部留证</td></tr></tbody></table><h2 id="四、详细课表" tabindex="-1"><a class="header-anchor" href="#四、详细课表" aria-hidden="true">#</a> 四、详细课表</h2><h3 id="阶段-0-建立地图" tabindex="-1"><a class="header-anchor" href="#阶段-0-建立地图" aria-hidden="true">#</a> 阶段 0：建立地图</h3><ol><li>Kubernetes 到底在解决什么：从 <code>docker run</code> 到持续纠偏</li><li>第一次完整实操：创建、观察、访问、看日志、清理 Pod</li><li>从实操反推 YAML：apiVersion、kind、metadata、spec</li><li>集群组件与 kubectl 的基础证据链</li></ol><h3 id="阶段-1-工作负载" tabindex="-1"><a class="header-anchor" href="#阶段-1-工作负载" aria-hidden="true">#</a> 阶段 1：工作负载</h3><ol start="5"><li>Pod 生命周期：从 Pending 到 Running</li><li>多容器 Pod：共享网络/存储与 Sidecar 边界</li><li>标签与选择器：Kubernetes 对象的“连接器”</li><li>Deployment 与 ReplicaSet：副本、自愈和所有者关系</li><li>发布工程：滚动更新、暂停、回滚与版本证据</li><li>Job / CronJob：一次性与周期性任务</li></ol><h3 id="阶段-2-配置与访问" tabindex="-1"><a class="header-anchor" href="#阶段-2-配置与访问" aria-hidden="true">#</a> 阶段 2：配置与访问</h3><ol start="11"><li>Namespace：隔离边界与它不能解决的问题</li><li>ConfigMap / Secret：配置与镜像解耦</li><li>Service：为什么 Pod 有 IP 还需要稳定入口</li><li>DNS 与服务发现：名字如何变成地址</li><li>Ingress：HTTP 流量如何进入集群</li><li>网络排障：从客户端逐跳验证到 Pod</li></ol><h3 id="阶段-3-数据与可靠性" tabindex="-1"><a class="header-anchor" href="#阶段-3-数据与可靠性" aria-hidden="true">#</a> 阶段 3：数据与可靠性</h3><ol start="17"><li>容器文件系统与 Volume：哪些数据会消失</li><li>PV / PVC / StorageClass：存储供需模型</li><li>StatefulSet：稳定身份、顺序和存储</li><li>存活、就绪、启动探针：三种“健康”不能混用</li><li>requests / limits：调度承诺和运行边界</li><li>优雅终止与可用性：从 SIGTERM 到流量摘除</li></ol><h3 id="阶段-4-调度与安全" tabindex="-1"><a class="header-anchor" href="#阶段-4-调度与安全" aria-hidden="true">#</a> 阶段 4：调度与安全</h3><ol start="23"><li>scheduler 如何做决定，Pending 如何读</li><li>nodeSelector、亲和性、污点与容忍</li><li>ServiceAccount 与 RBAC：谁可以对什么做什么</li><li>SecurityContext 与 Pod Security Standards</li><li>NetworkPolicy 与镜像/Secret 安全边界</li></ol><h3 id="阶段-5-可观测与排障" tabindex="-1"><a class="header-anchor" href="#阶段-5-可观测与排障" aria-hidden="true">#</a> 阶段 5：可观测与排障</h3><ol start="28"><li>Events、日志与状态：证据的时间顺序</li><li>exec、port-forward、临时调试容器</li><li>CPU、内存、OOM、驱逐与资源故障</li><li>网络/DNS 故障树</li><li>控制面与节点异常的判断边界</li><li>综合故障挑战：只给现象，不给答案</li></ol><h3 id="阶段-6-交付与运维" tabindex="-1"><a class="header-anchor" href="#阶段-6-交付与运维" aria-hidden="true">#</a> 阶段 6：交付与运维</h3><ol start="34"><li>Kustomize：原生 YAML 的环境差异</li><li>Helm：Chart、values、升级和回滚</li><li>生产变更：版本固定、发布验证与回退点</li><li>集群安装与生命周期：Docker Desktop、kind、kubeadm、托管 K8s 的边界</li><li>高可用、备份恢复、升级与容量规划认知</li><li>监控、日志、告警与 SLO 入门</li></ol><h3 id="结业项目" tabindex="-1"><a class="header-anchor" href="#结业项目" aria-hidden="true">#</a> 结业项目</h3><ol start="40"><li>部署一个含 Web、API、数据库的应用，完成：</li></ol><ul><li>配置与 Secret 外置</li><li>Service / Ingress 访问</li><li>持久化与备份说明</li><li>健康检查和资源限制</li><li>滚动升级与回滚</li><li>RBAC 最小权限</li><li>至少 5 个故障注入及证据化复盘</li></ul><h2 id="五、暂时不深挖的内容" tabindex="-1"><a class="header-anchor" href="#五、暂时不深挖的内容" aria-hidden="true">#</a> 五、暂时不深挖的内容</h2><p>Operator/CRD 开发、Istio/eBPF 深度原理、超大规模调度优化、多集群管理，不适合放在零基础主线里。主课结束后再按工作需要选修。</p><p>CKA 也不是本课程的第一目标。先获得真实理解和排障能力，再做考试题型训练会更稳。</p><h2 id="六、版本与资料原则" tabindex="-1"><a class="header-anchor" href="#六、版本与资料原则" aria-hidden="true">#</a> 六、版本与资料原则</h2><ul><li>实验以本机集群的实际 API 为准，不死背网络文章里的旧参数。</li><li>课堂命令先在本机验证，再写入讲义。</li><li>重要术语回到 Kubernetes 官方文档核对。</li><li>Kubernetes 小版本持续演进；具体支持周期、默认行为和废弃 API 在使用前重新确认。</li></ul><p>官方入口：</p>`,39),h={href:"https://kubernetes.io/docs/concepts/",target:"_blank",rel:"noopener noreferrer"},u={href:"https://kubernetes.io/docs/concepts/overview/components/",target:"_blank",rel:"noopener noreferrer"},b={href:"https://kubernetes.io/docs/tutorials/kubernetes-basics/",target:"_blank",rel:"noopener noreferrer"},v={href:"https://kubernetes.io/docs/reference/kubectl/",target:"_blank",rel:"noopener noreferrer"};function g(p,m){const t=s("ExternalLinkIcon");return a(),d("div",null,[c,e("ul",null,[e("li",null,[e("a",h,[i("Kubernetes 概念"),l(t)])]),e("li",null,[e("a",u,[i("集群组件"),l(t)])]),e("li",null,[e("a",b,[i("官方基础教程"),l(t)])]),e("li",null,[e("a",v,[i("kubectl 参考"),l(t)])])])])}const f=r(o,[["render",g],["__file","00-课程总纲.html.vue"]]);export{f as default};
